-- Products. Safe to run on an existing database: only creates the table if it is missing.
-- It never drops, truncates or alters existing tables or data.
-- category_id / subcategory_id use exactly the same type/charset/collation as category.id / subcategory.id (CHAR(36) ascii)
-- so the foreign keys work. ON DELETE RESTRICT: a category or subcategory that still has products cannot be deleted.
-- Category and subcategory NAMES are not duplicated here: the API joins them, so they never go stale after a rename.
-- discount_amount / discount_percent are generated by MySQL from mrp and selling_price (cannot get out of sync).
-- image_url stores only a URL string (never binary data). Prices are GST-inclusive, as MRP is in India.
CREATE TABLE IF NOT EXISTS product (
  id               CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL COMMENT 'UUID, generated by the API',
  category_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  subcategory_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  product_name     VARCHAR(200) NOT NULL,
  brand            VARCHAR(100) NULL,
  mrp              DECIMAL(10,2) NOT NULL,
  selling_price    DECIMAL(10,2) NOT NULL,
  discount_amount  DECIMAL(10,2) AS (mrp - selling_price) STORED,
  discount_percent DECIMAL(5,2)  AS (ROUND((mrp - selling_price) / mrp * 100, 2)) STORED,
  gst_percent      DECIMAL(5,2) NOT NULL DEFAULT 0,
  description      TEXT NULL,
  image_url        VARCHAR(500) NULL,
  stock_quantity   INT UNSIGNED NOT NULL DEFAULT 0,
  specifications   JSON NULL COMMENT 'ordered list: [{"name": "...", "value": "..."}]',
  status           TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = active, 0 = inactive',
  created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_product_category (category_id),
  KEY idx_product_subcategory (subcategory_id),
  KEY idx_product_brand (brand),
  KEY idx_product_selling_price (selling_price),
  KEY idx_product_status (status),
  KEY idx_product_created_at (created_at),
  CONSTRAINT chk_product_mrp CHECK (mrp > 0),
  CONSTRAINT chk_product_selling_price CHECK (selling_price > 0 AND selling_price <= mrp),
  CONSTRAINT chk_product_gst CHECK (gst_percent >= 0 AND gst_percent <= 100),
  CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES category (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_product_subcategory FOREIGN KEY (subcategory_id) REFERENCES subcategory (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
